  if(module==='polls')fields+=field('Opciones · una por línea','options',(cfg.options||[]).join('\n'),'textarea','required rows="5" placeholder="Primera opción\nSegunda opción"')+'<label class="c-check"><input name="anonymous" type="checkbox" '+(cfg.anonymous!==false?'checked':'')+'>Votación anónima</label>'+select('Mostrar resultados','results',[['after_vote','Después de participar'],['after_close','Al cerrar la encuesta']],cfg.results||'after_vote');
