  if(module==='games')fields+=select('Tipo de propuesta','kind',[['dynamic','Dinámica para un encuentro'],['quiz','Juego de preguntas del equipo']],cfg.kind||'dynamic')+field('Materiales y duración','materials',cfg.materials||'','textarea','rows="3"')+'<div data-quiz-editor></div>'+button('Agregar pregunta','data-add-question',true);
  if(['bible','challenges'].includes(module))fields+='<h3>'+(module==='bible'?'Días y lecturas':'Pasos del desafío')+'</h3><div data-step-editor></div>'+button('Agregar un paso','data-add-step',true);
